{"file_path":"src/values.js","content":"/**
 * The value model. Every node carries its own type tag, so an integer stays
 * apart from a float and an array of tables stays apart from a plain array.
 */

export class ConfError extends Error {
  constructor(line, reason) {
    super(reason)
    this.line = line
    this.reason = reason
  }
}

export function makeTable(explicit = false) {
  return { type: 'table', props: new Map(), explicit }
}

export function makeArray(tableArray = false) {
  return { type: 'array', items: [], tableArray }
}

export function scalar(type, value) {
  return { type, value }
}

/** Compares two strings by unicode code point. */
export function compareKeys(a, b) {
  const left = Array.from(a)
  const right = Array.from(b)
  const n = Math.min(left.length, right.length)
  for (let i = 0; i < n; i += 1) {
    const x = left[i].codePointAt(0)
    const y = right[i].codePointAt(0)
    if (x !== y) return x < y ? -1 : 1
  }
  if (left.length === right.length) return 0
  return left.length < right.length ? -1 : 1
}

/** The keys of a table, in ascending code point order. */
export function sortedKeys(table) {
  return [...table.props.keys()].sort(compareKeys)
}

export function joinPath(parts) {
  return parts.join('.')
}
"}

