{"file_path":"src/parse.js","content":"/**
 * The parser. It reads the configuration document one line at a time and
 * builds the tree of tables, arrays and scalars described by it.
 */

import { ConfError, makeArray, makeTable, scalar, joinPath } from './values.js'

const DIGITS = '[0-9]+(?:_[0-9]+)*'
const INT_RE = new RegExp(`^[+-]?${DIGITS}$`)
const FLOAT_RE = new RegExp(`^[+-]?${DIGITS}(?:\\.${DIGITS})?(?:[eE][+-]?${DIGITS})?$`)
const BARE_RE = /[A-Za-z0-9_-]/

function isSpace(ch) {
  return ch === ' ' || ch === '\t'
}

function isComment(ch) {
  return ch === '#' || ch === ';'
}

/** One line of the document, scanned left to right. */
class Scanner {
  constructor(text, line) {
    this.text = text
    this.line = line
    this.pos = 0
  }

  get done() {
    return this.pos >= this.text.length
  }

  peek(offset = 0) {
    return this.text[this.pos + offset]
  }

  skipSpace() {
    while (!this.done && isSpace(this.peek())) this.pos += 1
  }

  /** True once nothing but a comment is left on the line. */
  atEnd() {
    return this.done || isComment(this.peek())
  }

  fail(reason) {
    return new ConfError(this.line, reason)
  }
}

function parseBasicString(sc) {
  sc.pos += 1
  let out = ''
  for (;;) {
    if (sc.done) throw sc.fail('unterminated string')
    const ch = sc.peek()
    sc.pos += 1
    if (ch === '"') return out
    if (ch !== '\\') {
      out += ch
      continue
    }
    if (sc.done) throw sc.fail('unterminated string')
    const esc = sc.peek()
    sc.pos += 1
    if (esc === '"') out += '"'
    else if (esc === '\\') out += '\\'
    else if (esc === 'n') out += '\n'
    else if (esc === 't') out += '\t'
    else if (esc === 'r') out += '\r'
    else if (esc === '0') out += '\0'
    else if (esc === 'u') {
      const hex = sc.text.slice(sc.pos, sc.pos + 4)
      if (!/^[0-9A-Fa-f]{4}$/.test(hex)) throw sc.fail('invalid escape \\u')
      sc.pos += 4
      out += String.fromCharCode(parseInt(hex, 16))
    } else throw sc.fail(`invalid escape \\${esc}`)
  }
}

function parseLiteralString(sc) {
  sc.pos += 1
  let out = ''
  for (;;) {
    if (sc.done) throw sc.fail('unterminated string')
    const ch = sc.peek()
    sc.pos += 1
    if (ch === "'") return out
    out += ch
  }
}

/** A bare word or a quoted string used as a name. */
function parseName(sc) {
  if (sc.done) throw sc.fail('expected a name')
  const ch = sc.peek()
  if (ch === '"') return parseBasicString(sc)
  if (ch === "'") return parseLiteralString(sc)
  let out = ''
  while (!sc.done && BARE_RE.test(sc.peek())) {
    out += sc.peek()
    sc.pos += 1
  }
  if (out === '') throw sc.fail('expected a name')
  return out
}

/** Names joined by dots, with spaces and tabs allowed around each dot. */
function parseDottedName(sc) {
  const parts = [parseName(sc)]
  for (;;) {
    const mark = sc.pos
    sc.skipSpace()
    if (sc.done || sc.peek() !== '.') {
      sc.pos = mark
      return parts
    }
    sc.pos += 1
    sc.skipSpace()
    parts.push(parseName(sc))
  }
}

function classifyWord(sc, word) {
  if (word === 'true') return scalar('boolean', true)
  if (word === 'false') return scalar('boolean', false)
  const plain = word.replace(/_/g, '')
  if (INT_RE.test(word)) return scalar('integer', Number(plain))
  if (FLOAT_RE.test(word)) return scalar('float', Number(plain))
  throw sc.fail(`invalid value ${word}`)
}

function parseArray(sc, path) {
  sc.pos += 1
  const array = makeArray(false)
  for (;;) {
    sc.skipSpace()
    if (sc.atEnd()) throw sc.fail('unterminated array')
    if (sc.peek() === ']') {
      sc.pos += 1
      return array
    }
    const item = parseValue(sc, path.concat(`[${array.items.length}]`))
    array.items.push(item)
    sc.skipSpace()
    if (sc.atEnd()) throw sc.fail('unterminated array')
    if (sc.peek() === ',') {
      sc.pos += 1
      continue
    }
    if (sc.peek() === ']') {
      sc.pos += 1
      return array
    }
    throw sc.fail('unterminated array')
  }
}

function parseInlineTable(sc, path) {
  sc.pos += 1
  const table = makeTable(false)
  sc.skipSpace()
  if (sc.atEnd()) throw sc.fail('unterminated inline table')
  if (sc.peek() === '}') {
    sc.pos += 1
    return table
  }
  for (;;) {
    sc.skipSpace()
    if (sc.atEnd()) throw sc.fail('unterminated inline table')
    const names = parseDottedName(sc)
    sc.skipSpace()
    if (sc.atEnd() || sc.peek() !== '=') throw sc.fail('expected = in an inline table')
    sc.pos += 1
    sc.skipSpace()
    const value = parseValue(sc, path.concat(names))
    assign(sc, table, path, names, value)
    sc.skipSpace()
    if (sc.atEnd()) throw sc.fail('unterminated inline table')
    if (sc.peek() === ',') {
      sc.pos += 1
      continue
    }
    if (sc.peek() === '}') {
      sc.pos += 1
      return table
    }
    throw sc.fail('unterminated inline table')
  }
}

/** One value, of any of the kinds the document may carry. */
function parseValue(sc, path) {
  if (sc.atEnd()) throw sc.fail('expected a value')
  const ch = sc.peek()
  if (ch === '"') return scalar('string', parseBasicString(sc))
  if (ch === "'") return scalar('string', parseLiteralString(sc))
  if (ch === '[') return parseArray(sc, path)
  if (ch === '{') return parseInlineTable(sc, path)
  let word = ''
  while (!sc.done && !isSpace(sc.peek()) && !',]}'.includes(sc.peek())) {
    word += sc.peek()
    sc.pos += 1
  }
  if (word === '') throw sc.fail('expected a value')
  return classifyWord(sc, word)
}

/** Walks the dots of a name, making the tables they pass through. */
function walk(sc, table, base, names) {
  let node = table
  const seen = base.slice()
  for (const name of names) {
    seen.push(name)
    let next = node.props.get(name)
    if (next === undefined) {
      next = makeTable(false)
      node.props.set(name, next)
    }
    if (next.type === 'array' && next.tableArray && next.items.length > 0) {
      next = next.items[next.items.length - 1]
    }
    if (next.type !== 'table') throw sc.fail(`${joinPath(seen)} is not a table`)
    node = next
  }
  return node
}

function assign(sc, table, base, names, value) {
  const parent = walk(sc, table, base, names.slice(0, -1))
  const last = names[names.length - 1]
  const path = joinPath(base.concat(names))
  if (parent.props.has(last)) throw sc.fail(`key ${path} is defined twice`)
  parent.props.set(last, value)
}

/** Resolves a `[name]` header, making the table it names current. */
function openTable(sc, root, names) {
  const parent = walk(sc, root, [], names.slice(0, -1))
  const last = names[names.length - 1]
  const path = joinPath(names)
  let node = parent.props.get(last)
  if (node === undefined) {
    node = makeTable(true)
    parent.props.set(last, node)
    return { node, path: names }
  }
  if (node.type !== 'table') throw sc.fail(`${path} is not a table`)
  if (node.explicit) throw sc.fail(`table ${path} is defined twice`)
  node.explicit = true
  return { node, path: names }
}

/** Resolves a `[[name]]` header, appending a fresh table to the array. */
function openArrayTable(sc, root, names) {
  const parent = walk(sc, root, [], names.slice(0, -1))
  const last = names[names.length - 1]
  const path = joinPath(names)
  let node = parent.props.get(last)
  if (node === undefined) {
    node = makeArray(true)
    parent.props.set(last, node)
  }
  if (node.type !== 'array' || !node.tableArray) {
    throw sc.fail(`${path} is not an array of tables`)
  }
  const fresh = makeTable(true)
  node.items.push(fresh)
  return { node: fresh, path: names }
}

function parseHeader(sc, root) {
  sc.pos += 1
  const doubled = !sc.done && sc.peek() === '['
  if (doubled) sc.pos += 1
  sc.skipSpace()
  if (sc.done || isComment(sc.peek())) throw sc.fail('expected a name')
  const names = parseDottedName(sc)
  sc.skipSpace()
  if (sc.done || sc.peek() !== ']') throw sc.fail('unterminated table header')
  sc.pos += 1
  if (doubled) {
    if (sc.done || sc.peek() !== ']') throw sc.fail('unterminated table header')
    sc.pos += 1
  }
  sc.skipSpace()
  if (!sc.atEnd()) throw sc.fail('trailing text after a table header')
  return doubled ? openArrayTable(sc, root, names) : openTable(sc, root, names)
}

/** Splits the document the way the specification asks for. */
export function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/** Parses a whole document, returning its root table. */
export function parseDocument(text) {
  const root = makeTable(true)
  let current = root
  let currentPath = []
  const lines = splitLines(text)
  for (let i = 0; i < lines.length; i += 1) {
    const sc = new Scanner(lines[i], i + 1)
    sc.skipSpace()
    if (sc.done || isComment(sc.peek())) continue
    if (sc.peek() === '[') {
      const opened = parseHeader(sc, root)
      current = opened.node
      currentPath = opened.path
      continue
    }
    const names = parseDottedName(sc)
    sc.skipSpace()
    if (sc.done || sc.peek() !== '=') throw sc.fail('expected key = value')
    sc.pos += 1
    sc.skipSpace()
    const value = parseValue(sc, currentPath.concat(names))
    sc.skipSpace()
    if (!sc.atEnd()) throw sc.fail('trailing text after a value')
    assign(sc, current, currentPath, names, value)
  }
  return root
}
"}

