/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { readFileSync } from 'node:fs'
import { parseDocument } from './parse.js'
import { toJson, toKeys } from './format.js'
import { ConfError } from './values.js'

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'json' && mode !== 'keys')) {
    process.stderr.write('error: usage: cli.js json|keys\n')
    process.exit(2)
  }
  let output
  try {
    const root = parseDocument(readStdin())
    output = mode === 'json' ? toJson(root) : toKeys(root)
  } catch (err) {
    if (err instanceof ConfError) {
      process.stderr.write(`error: line ${err.line}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }
  process.stdout.write(output)
}

main(process.argv.slice(2))
"}

